const page=new TextDecoder().decode(Uint8Array.from(atob(""),c=>c.charCodeAt(0)));
const fridgeImage="";
const imageBytes=()=>Uint8Array.from(atob(fridgeImage),c=>c.charCodeAt(0));
const json=(d,s=200)=>new Response(JSON.stringify(d),{status:s,headers:{"content-type":"application/json;charset=utf-8"}});
const prompt=b=>b.type==="scan"?"识别图片中的食品或小票。只返回 JSON 对象，根字段 items；每一项包含 name, category, quantity, unit, expiry_date, location。看不清不要猜。":b.type==="shelf"?"你是食品保存期限助手。食材："+b.ingredient+"；存放方式："+b.storage+"；今天："+b.currentDate+"；本地规则："+JSON.stringify(b.fallback||null)+"。只返回 JSON 对象：{\"estimatedDays\":数字,\"confidence\":0到1之间的数字,\"reason\":\"简短原因\"}。不要 Markdown。":b.type==="expiry"?"估算食材保质期。今天是 "+new Date().toISOString().slice(0,10)+"；食材："+b.name+"；保存位置："+b.place+"。只返回 JSON 对象，字段 expiry_date，格式 YYYY-MM-DD。":"你是家庭厨房助手。只基于真实库存设计恰好 3 道实用中文家常菜。库存："+(b.inventory||[]).map(x=>x.name+" "+x.quantity+(x.unit||"份")).join("；")+"。偏好和忌口："+(b.preference||"无")+"。食材必须使用库存中的名字和准确用量，不得虚构。若库存有至少 2 个番茄和 3 个鸡蛋，第一道必须是番茄炒蛋，且用量为番茄 2 个、鸡蛋 3 个。只返回 JSON，不要 Markdown。格式：{\"recipes\":[{\"id\":\"string\",\"title\":\"string\",\"description\":\"string\",\"cookTime\":20,\"servings\":2,\"ingredients\":[{\"name\":\"string\",\"quantity\":1,\"unit\":\"个\"}],\"steps\":[\"步骤\"]}]}";
const parseModelJson=t=>{const s=String(t||"").trim().replace(/^```(?:json)?\s*|\s*```$/g,""),a=s.indexOf("{"),z=s.lastIndexOf("}");return JSON.parse(a>=0&&z>a?s.slice(a,z+1):s)};
export default{async fetch(req,env){const path=new URL(req.url).pathname;if(path==="/assets/fridge-home.png")return new Response(imageBytes(),{headers:{"content-type":"image/png","cache-control":"public,max-age=86400"}});if(path!=="/api/gemini"&&path!=="/api/recipes/generate"&&path!=="/api/shelf-life/estimate")return new Response(page,{headers:{"content-type":"text/html;charset=utf-8"}});if(req.method!=="POST")return json({error:"只支持 POST 请求"},405);const apiKey=env.AGNES_API_KEY||env.MODEL_API_KEY,baseUrl=(env.AGNES_BASE_URL||env.MODEL_BASE_URL||"https://apihub.agnes-ai.com/v1").replace(/\/$/,""),model=env.AGNES_MODEL||env.MODEL_NAME||"agnes-2.5-flash";if(!apiKey)return json({error:"Agnes AI 服务尚未配置"},503);try{let b=await req.json();if(path==="/api/recipes/generate")b={type:"recipe",inventory:b.inventory||[],preference:b.cuisine||b.preference||""};if(path==="/api/shelf-life/estimate")b={type:"shelf",ingredient:b.ingredient||"",storage:b.storage||"fridge",currentDate:b.currentDate||new Date().toISOString().slice(0,10),fallback:b.fallback||null};if(b.type==="recipe"&&!(b.inventory||[]).length)return json({error:"EMPTY_INVENTORY"},400);if(!["scan","recipe","expiry","shelf"].includes(b.type))return json({error:"未知请求"},400);let content=prompt(b);if(b.type==="scan"){const m=String(b.imageData||"").match(/^data:([^;]+);base64,(.+)$/);if(!m)return json({error:"请先选择图片"},400);content=[{type:"text",text:prompt(b)},{type:"image_url",image_url:{url:b.imageData}}]}const r=await fetch(baseUrl+"/chat/completions",{method:"POST",headers:{"content-type":"application/json","authorization":"Bearer "+apiKey},body:JSON.stringify({model,response_format:{type:"json_object"},messages:[{role:"user",content}],temperature:.2,max_tokens:2400})});if(!r.ok){const detail=await r.json().catch(()=>null),status=r.status,msg=String(detail?.error?.message||detail?.message||"");const error=status===400?"Agnes 请求格式有误，请稍后重试。":status===401||status===403?"Agnes Key 无效或没有 API 权限。":status===404?"Agnes 模型暂时不可用，请稍后重试。":status===429?"Agnes 暂时达到调用额度，请稍后再试。":"Agnes AI 服务暂时不可用，请稍后重试。";console.error("Agnes request failed",status,msg.slice(0,240));return json({error,code:status},502)}const d=await r.json(),t=d?.choices?.[0]?.message?.content;return t?json(parseModelJson(t)):json({error:"Agnes 没有返回可用结果，请重试。"},502)}catch(e){console.error("Agnes handler failed",String(e?.message||e));return json({error:"Agnes 结果处理失败，请稍后重试。"},500)}}};
